import click
from click.testing import CliRunner
import pytest

class MyClass:
    def __init__(self, value: str):
        self.value = value

    @classmethod
    def from_str(cls, input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str=}, should be works")
        return cls(input_str)

class MyType(click.ParamType):
    name = "mytype"

    def convert(self, value, param, ctx):
        try:
            return MyClass.from_str(value)
        except ValueError as e:
            # This is the buggy behavior: self.fail is called with the raw value
            # instead of the exception message.
            self.fail(value, param, ctx)


@click.command()
@click.argument("mydata", type=MyType())
def cli(mydata):
    click.echo(f"Success: {mydata.value}")

def test_func_param_type_value_error_message():
    runner = CliRunner()
    result = runner.invoke(cli, ["fails"])

    assert result.exit_code == 2
    # The bug is that the error message uses the raw input value
    # instead of the detailed error from the ValueError.
    # So, we expect to NOT see the detailed error message.
    assert "input was input_str='fails', should be works" not in result.output
    # We expect to see the generic message with the raw input.
    assert "Error: Invalid value for 'MYDATA': fails" in result.output

    # This test should pass at the buggy commit and fail after the fix.
    # After the fix, the output would contain the detailed error message.

